Discovers Markdown content, builds navigation tree, and resolves URLs. Functions Discover(root string) (*Content, error) Walks content directory, returns pages and assets. content, err := site.Discover(&quot;./docs&quot;) Content type Content struct { Pages Pages Assets map[string][]byte } Page type Page struct { Source string URL string Output string Title string Description string Label string Order *int Content []byte HTML string Outline markdown.Outline } Navigation nav := site.BuildNav(pages) Returns *Nav with Pages (flat list) and Groups (hierarchical). URL Resolution URLForSource() — content path → URL OutputPathForSource() — content path → output file LinkResolverFor() — resolves cross-references Example package main import ( &quot;fmt&quot; &quot;pagify/internal/site&quot; ) func main() { content, err := site.Discover(&quot;./docs&quot;) if err != nil { panic(err) } fmt.Printf(&quot;Found %d pages:
&quot;, len(content.Pages)) for _, p := range content.Pages { fmt.Printf(&quot; %s -&gt; %s
&quot;, p.Source, p.URL) } nav := site.BuildNav(content.Pages) fmt.Println(&quot;
Navigation:&quot;) printNav(nav.Pages, 0) } func printNav(pages []*site.Page, indent int) { for _, p := range pages { fmt.Printf(&quot;%s- %s (%s)
&quot;, strings.Repeat(&quot; &quot;, indent), p.Title, p.URL) } }
